// ---------------------------------------------------------------- car frame → world coordinates
function frame(model) {
  const [cx, cy] = model.center, L = model.half_len, W = model.half_wid, [z0, z1] = model.z;
  const F = model.fwd, R = model.right;
  const world = ([f, r, h]) => [cx + f * L * F[0] + r * W * R[0], cy + f * L * F[1] + r * W * R[1], z0 + h * (z1 - z0)];
  const dir = ([vf, vr, vh]) => {
    const v = [vf * F[0] + vr * R[0], vf * F[1] + vr * R[1], vh];
    const n = Math.hypot(...v) || 1;
    return v.map((x) => x / n);
  };
  return { world, dir, L };
}

function camFor(st, zoneId) {
  const fr = frame(st.data.model);
  if (!zoneId) {
    const target = fr.world([0, 0, 0.42]);
    const d = fr.dir([0.85, -0.95, 0.42]);
    return { eye: target.map((t, i) => t + d[i] * fr.L * 2.75), target };
  }
  const z = st.data.zones[zoneId];
  const target = fr.world(z.pos);
  const d = fr.dir(z.view);
  return { eye: target.map((t, i) => t + d[i] * fr.L * z.dist), target };
}

function fly(st, zoneId, secs) {
  if (!st.api || !st.ready) return;
  const c = camFor(st, zoneId);
  // a background tab doesn't run the viewer's animation loop — jump instead of a transition that never ends
  const t = document.hidden ? 0 : (secs === undefined ? 1.4 : secs);
  st.api.setCameraLookAt(c.eye, c.target, t, () => schedulePins(st));
}

// ---------------------------------------------------------------- viewer
  stopTour(st);
  fly(st, r.zone);
  renderPanel(st); renderRail(st); schedulePins(st);
}

function overview(st) {
  st.zone = null; st.req = null;
  stopTour(st);
  fly(st, null);
  renderPanel(st); renderRail(st); schedulePins(st);
}

function stopTour(st) {
  if (st.tour) { clearInterval(st.tour); st.tour = null; }
  if (st.tourBtn) st.tourBtn.classList.remove("on");
}

function startTour(st) {
  if (st.tour) { stopTour(st); return; }
  const stats = zoneStats(st);
  const order = Object.keys(st.data.zones).filter((z) => stats[z]);

