.cs-pin-wrap:hover .cs-label,
.cs-pin-wrap:focus-within .cs-label,
.cs-pin-wrap[data-hover="1"] .cs-label,
.cs-pin-wrap[data-selected="1"] .cs-label { opacity: 1; transform: translate(0, -50%); }

