569	  const target = zone ? zoneToWorld(zone.pos, frame) : null;
570	  const xray = !!selectedZone && INTERIOR_ZONES.has(selectedZone);
571	
572	  const placeholder = <Placeholder onReady={onReady} />;
573	
574	  return (
575	    <>
576	      <Studio shadowKey={`${modelUrl ?? "placeholder"}:${modelFailed}:${carVersion}`} />
577	      {modelUrl && !modelFailed ? (
578	        <ModelBoundary key={modelUrl} fallback={placeholder} onError={onModelError}>
579	          <Suspense fallback={null}>
580	            <GltfCar url={modelUrl} orientation={orientation} onReady={onReady} />
581	          </Suspense>
582	        </ModelBoundary>
583	      ) : (
584	        placeholder
585	      )}
586	      <ZoneFocus carRef={carRef} carVersion={carVersion} target={target} xray={xray} reduced={reduced} />
587	      <Pins
588	        zones={zones}
589	        hotspots={hotspots}
590	        frame={frame}
591	        selectedZone={selectedZone}
592	        hoverZone={hoverZone}
593	        xray={xray}
594	        onSelectZone={onSelectZone}
595	      />
596	      <CameraRig frame={frame} zone={zone} compact={compact} reduced={reduced} />
597	    </>
598	  );
599	}
600	
601	function LoadingLine() {
602	  const { active, progress } = useProgress();
603	  if (!active) return null;
604	  const pct = Math.round(progress);
605	  return (
606	    <div className="cs-progress" role="status" aria-live="polite">
607	      <div className="cs-progress-track">
608	        <div className="cs-progress-bar" style={{ width: `${pct}%` }} />
609	      </div>
