SP=/private/tmp/claude-501/-Users-atahankilic-Documents-ehl-munich-final/c7f79221-413b-46d1-a535-ff2a11d3d1b2/scratchpad; cp /Users/atahankilic/Documents/ehl-munich-final/web/src/three/frame.ts $SP/frame.ts && cat > $SP/frame_check.ts <<'EOF'
import assert from "node:assert/strict";
import { zoneToWorld, frameDir, orientationMatrix, WORLD_RIGHT, poseFor } from "./frame.ts";
const F = { L: 2.4, W: 0.95, H: 1.44 };
assert.deepEqual(WORLD_RIGHT, [0, 0, 1]);
assert.deepEqual(zoneToWorld([1, 0, 0], F), [2.4, 0, 0]);
assert.deepEqual(zoneToWorld([0, 1, 1], F), [0, 1.44, 0.95]);
assert.deepEqual(zoneToWorld([0, -1, 0.5], F), [0, 0.72, -0.95]);
const d = frameDir([0, 0, 2]); assert.deepEqual(d, [0, 1, 0]);
const m = orientationMatrix({ up: "+z", front: "-y" })!;
const mul = (v: number[]) => [0, 1, 2].map((r) => m[r * 3] * v[0] + m[r * 3 + 1] * v[1] + m[r * 3 + 2] * v[2]);
assert.deepEqual(mul([0, -1, 0]).map((x) => x + 0), [1, 0, 0]);
assert.deepEqual(mul([0, 0, 1]).map((x) => x + 0), [0, 1, 0]);
assert.equal(orientationMatrix({ up: "+y", front: "-y" }), null);
const p = poseFor(null, F); assert.ok(p.eye[2] < 0 && p.eye[0] > 0, "overview is front-left");
console.log("frame checks OK", p);
EOF
cd $SP && node frame_check.ts

